/**
 * @brief Draw the 64x64 logo at the given top-left position (used in the page header bar).
 *        0x0000 source pixels are skipped so the existing background shows through.
 */
Display_Result_t Display_PagesDrawHeaderLogo(uint16_t x, uint16_t y)
{
  uint16_t row;
  uint16_t col;
  uint32_t offset;
  uint16_t color;
  uint8_t  lo;
  uint8_t  hi;

  if (Display_GfxIsReady() == 0U) { return DISPLAY_NOT_READY; }

  for (row = 0U; row < DISPLAY_HEADER_LOGO_HEIGHT; row++) {
    for (col = 0U; col < DISPLAY_HEADER_LOGO_WIDTH; col++) {
      offset = ((uint32_t)row * (uint32_t)DISPLAY_HEADER_LOGO_WIDTH + (uint32_t)col) * 2U;
      lo     = s_header_logo_map[offset];
      hi     = s_header_logo_map[offset + 1U];
      color  = (uint16_t)(((uint16_t)hi << 8U) | (uint16_t)lo);
      if (color != DISPLAY_HEADER_LOGO_TRANSPARENT_COLOR) { (void)Display_GfxDrawPixel((uint16_t)(x + col), (uint16_t)(y + row), color); }
    }
  }

  return DISPLAY_OK;
}
